{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(approx_quantile(duration/1e6,0.5),1) med, ROUND(approx_quantile(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name IN ('GET','POST') GROUP BY 1,2,3 ORDER BY 2,3",
          "claim": "Seat GET client spans have p95 ~423 ms in abnormal while median stays ~4 ms; POST client spans unchanged."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind k, COUNT(*) n, ROUND(approx_quantile(duration/1e6,0.5),1) med, ROUND(approx_quantile(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-config-service' AND attr_span_kind='Server' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, COUNT(*), ROUND(approx_quantile(duration/1e6,0.5),1), ROUND(approx_quantile(duration/1e6,0.95),1) FROM normal_traces WHERE service_name='ts-config-service' AND attr_span_kind='Server' GROUP BY 1,2,3,4",
          "claim": "ts-config-service server spans stay at about 4 ms p95 in both periods, so the callee is not slow."
        },
        {
          "kind": "trace",
          "sql": "WITH a AS (SELECT service_name, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE attr_span_kind='Server' GROUP BY 1,2), n AS (SELECT service_name, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM normal_traces WHERE attr_span_kind='Server' GROUP BY 1,2) SELECT a.service_name, a.span_name, n.p95 np95, a.p95 ap95 FROM a LEFT JOIN n USING (service_name, span_name) WHERE a.p95 > 1.5*COALESCE(n.p95,0)+5 ORDER BY ap95 DESC",
          "claim": "Seat left_tickets server p95 rises from ~13 ms to ~431 ms; ui-dashboard travel-plan endpoints rise to ~4 s."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, ROUND(approx_quantile(c.duration/1e6,0.5),1) tp_client_med, ROUND(approx_quantile(c.duration/1e6,0.95),1) tp_client_p95, COUNT(*) n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' UNION ALL SELECT 'norm', ROUND(approx_quantile(c.duration/1e6,0.5),1), ROUND(approx_quantile(c.duration/1e6,0.95),1), COUNT(*) FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service'",
          "claim": "Travel-plan client calls to seat rise from p95 ~11 ms to ~855 ms in abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH a AS (SELECT service_name, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE attr_span_kind='Server' GROUP BY 1,2), n AS (SELECT service_name, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM normal_traces WHERE attr_span_kind='Server' GROUP BY 1,2) SELECT a.service_name, a.span_name, n.p95 np95, a.p95 ap95 FROM a LEFT JOIN n USING (service_name, span_name) WHERE a.p95 > 1.5*COALESCE(n.p95,0)+5 ORDER BY ap95 DESC",
          "claim": "Travel-plan cheapest server p95 rises ~107 ms to ~4166 ms, and the same ui-dashboard endpoint rises ~113 ms to ~4094 ms."
        }
      ]
    }
  ]
}
